{"file_path":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/Services/ExcelService.cs","content":"using System.Data;
using ClosedXML.Excel;

namespace ExcelPlanner.Services
{
    public class ExcelService
    {
        public XLWorkbook? LoadWorkbook(string filePath)
        {
            return new XLWorkbook(filePath);
        }

        public List<string> GetSheetNames(XLWorkbook workbook)
        {
            return workbook.Worksheets.Select(w => w.Name).ToList();
        }

        public DataTable? GetSheetData(XLWorkbook workbook, string sheetName)
        {
            var worksheet = workbook.Worksheet(sheetName);
            var range = worksheet.RangeUsed();

            if (range == null) return null;

            return range.AsTable().AsNativeDataTable();
        }
    }
}
