{"file_path":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/Services/ExcelService.cs","content":"using System.Data;
using ClosedXML.Excel;

namespace ExcelPlanner.Services
{
    public class ExcelService
    {
        public Task<XLWorkbook> LoadWorkbookAsync(string filePath)
        {
            if (string.IsNullOrEmpty(filePath))
                throw new ArgumentException("Đường dẫn file không hợp lệ.", nameof(filePath));

            return Task.Run(() => new XLWorkbook(filePath));
        }

        public List<string> GetSheetNames(XLWorkbook workbook)
        {
            if (workbook == null) throw new ArgumentNullException(nameof(workbook));
            return workbook.Worksheets.Select(w => w.Name).ToList();
        }

        public Task<DataTable?> GetSheetDataAsync(XLWorkbook workbook, string sheetName)
        {
            if (workbook == null) throw new ArgumentNullException(nameof(workbook));
            if (string.IsNullOrEmpty(sheetName)) throw new ArgumentException("Tên sheet không hợp lệ.", nameof(sheetName));

            return Task.Run(() =>
            {
                var worksheet = workbook.Worksheet(sheetName);
                var range = worksheet.RangeUsed();

                if (range == null) return null;

                return range.AsTable().AsNativeDataTable();
            });
        }

        public void SaveWorkbook(XLWorkbook workbook, string filePath)
        {
            if (workbook == null) throw new ArgumentNullException(nameof(workbook));
            workbook.SaveAs(filePath, true);
        }
    }
}
