{"file_path":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/Services/JsonTaskService.cs","content":"using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using ExcelPlanner.Models;

namespace ExcelPlanner.Services
{
    public class JsonTaskService
    {
        private readonly string _filePath;

        public JsonTaskService(string fileName = "tasks.json")
        {
            _filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, fileName);
        }

        public List<TaskItem> LoadTasks()
        {
            if (!File.Exists(_filePath))
                return new List<TaskItem>();

            try
            {
                var json = File.ReadAllText(_filePath);
                return JsonSerializer.Deserialize<List<TaskItem>>(json) ?? new List<TaskItem>();
            }
            catch (Exception)
            {
                // Nếu file bị lỗi định dạng, trả về danh sách rỗng để tránh crash ứng dụng
                return new List<TaskItem>();
            }
        }

        public void SaveTasks(List<TaskItem> tasks)
        {
            try
            {
                var options = new JsonSerializerOptions
                {
                    WriteIndented = true,
                    PropertyNamingPolicy = JsonNamingPolicy.CamelCase
                };
                var json = JsonSerializer.Serialize(tasks, options);
                File.WriteAllText(_filePath, json);
            }
            catch (Exception ex)
            {
                throw new IOException($"Không thể lưu file task: {ex.Message}");
            }
        }
    }
}
