  "name": "write_file",
  "arguments": {
    "file_path": "C:/Users/Xon/Desktop/ai_work/ExcelPlanner/Services/PdfReportService.cs",
    "content": "using QuestPDF.Fluent;\nusing QuestPDF.Helpers;\nusing QuestPDF.Infrastructure;\nusing ExcelPlanner.Models;\nusing System.Data;\n\nnamespace ExcelPlanner.Services\n{\n    public class PdfReportService\n    {\n        static PdfReportService()\n        {\n            // Kích hoạt giấy phép cộng đồng cho QuestPDF\n            QuestPDF.Settings.License = LicenseType.Community;\n        }\n\n        public void GenerateTaskReport(string filePath, string excelFileName, List<TaskItem> tasks)\n        {\n            Document.Create(container =>\n            {\n                container.Page(page =>\n                {\n                    page.Size(PageSizes.A4);\n                    page.Margin(40);\n                    page.Header().Element(BuildHeader(excelFileName));\n                    page.Content().PaddingVertical(20).Element(BuildContent(tasks));\n                    page.Footer().AlignCenter().Text(text =>\n                    {\n                        text.Span(\"Trang \");\n                        text.CurrentPageNumber();\n                        text.Span(\" / \");\n                        text.TotalPages();\n                    });\n                });\n            })\n            .GeneratePdf(filePath);\n        }\n\n        private static Action<IContainer> BuildHeader(string fileName)\n        {\n            return header =>\n            {\n                header.Row(row =>\n                {\n                    row.RelativeItem().Column(column =>\n                    {\n                        column.Item().Text($\"Báo cáo kế hoạch: {fileName}\")\n                            .FontSize(20).SemiBold().FontColor(Colors.Blue.Medium);\n                        column.Item().Text($\"Ngày xuất: {DateTime.Now:dd/MM/yyyy HH:mm}\")\n                            .FontSize(12).FontColor(Colors.Grey.Darken2);\n                    });\n                });\n                header.PaddingTop(10).BorderBottom(1).BorderColor(Colors.Grey.Lighten2);\n            };\n        }\n\n        private static Action<IContainer> BuildContent(List<TaskItem> tasks)\n        {\n            return content =>\n            {\n                if (!tasks.Any())\n                {\n                    content.AlignCenter().AlignMiddle().Text(\"Chưa có task nào trong danh sách.\").FontSize(14).FontColor(Colors.Grey.Medium);\n                    return;\n                }\n\n                content.Table(table =>\n                {\n                    table.ColumnsDefinition(columns =>\n                    {\n                        columns.RelativeColumn(1);\n                        columns.RelativeColumn(3);\n                    });\n\n                    table.Header(header =>\n                    {\n                        header.Cell().Element(CellStyle).Text(\"#\").Bold();\n                        header.Cell().Element(CellStyle).Text(\"Mô tả công việc\").Bold();\n                        \n                        static IContainer CellStyle(IContainer container) => \n                            container.BorderBottom(1).BorderColor(Colors.Grey.Lighten2).Padding(5);\n                    });\n\n                    foreach (var (task, index) in tasks.Select((t, i) => (t, i)))\n                    {\n                        table.Cell().Element(CellStyle).Text((index + 1).ToString());\n                        table.Cell().Element(CellStyle).Text(task.Description);\n                        \n                        static IContainer CellStyle(IContainer container) => \n                            container.BorderBottom(1).BorderColor(Colors.Grey.Lighten3).Padding(5);\n                    }\n                });\n            };\n        }\n    }\n}\n"
  }
}
