    "target_content": "using System.Data;\nusing System.IO;\nusing System.Windows;\nusing System.Windows.Controls;\nusing ClosedXML.Excel;\nusing Microsoft.Win32;\n\nnamespace ExcelPlanner\n{\n    public partial class MainWindow : Window\n    {\n        private XLWorkbook? _workbook;\n        private DataTable? _currentTable;\n        private List<TaskItem> _tasks = new();\n\n        public MainWindow()\n        {\n            InitializeComponent();\n            LbTasks.ItemsSource = _tasks;\n        }\n\n        private void OpenFile_Click(object sender, RoutedEventArgs e)\n        {\n            var dialog = new OpenFileDialog\n            {\n                Filter = \"Excel Files|*.xlsx;*.xls\",\n                Title = \"Chọn file Excel để xem và lập kế hoạch\"\n            };\n\n            if (dialog.ShowDialog() == true)\n            {\n                try\n                {\n                    _workbook = new XLWorkbook(dialog.FileName);\n                    CboSheets.ItemsSource = _workbook.Worksheets.Select(w => w.Name).ToList();\n                    if (CboSheets.Items.Count > 0)\n                    {\n                        CboSheets.SelectedIndex = 0;\n                    }\n                    TxtStatus.Text = $\"Đã mở: {Path.GetFileName(dialog.FileName)}\";\n                }\n                catch (Exception ex)\n                {\n                    MessageBox.Show($\"Lỗi đọc file: {ex.Message}\", \"Lỗi\", MessageBoxButton.OK, MessageBoxImage.Error);\n                }\n            }\n        }\n\n        private void CboSheets_SelectionChanged(object sender, SelectionChangedEventArgs e)\n        {\n            if (_workbook == null || CboSheets.SelectedItem == null) return;\n\n            var sheetName = CboSheets.SelectedItem.ToString();\n            if (string.IsNullOrEmpty(sheetName)) return;\n\n            try\n            {\n                var worksheet = _workbook.Worksheet(sheetName);\n                var range = worksheet.RangeUsed();\n                \n                if (range == null)\n                {\n                    TxtStatus.Text = $\"Sheet: {sheetName} (Trống)\";\n                    DgData.ItemsSource = null;\n                    _currentTable = null;\n                    return;\n                }\n\n                // Chuyển Worksheet sang DataTable để bind vào DataGrid\n                _currentTable = range.AsTable().AsNativeDataTable();\n                DgData.ItemsSource = _currentTable.DefaultView;\n                TxtStatus.Text = $\"Sheet: {sheetName} ({_currentTable.Rows.Count} dòng)\";\n            }\n            catch (Exception ex)\n            {\n                MessageBox.Show($\"Không thể đọc sheet '{sheetName}': {ex.Message}\", \"Lỗi dữ liệu\", MessageBoxButton.OK, MessageBoxImage.Warning);\n                TxtStatus.Text = \"Lỗi đọc sheet\";\n            }\n        }\n\n        private void DgData_SelectionChanged(object sender, SelectionChangedEventArgs e)\n        {\n            if (DgData.SelectedItem is DataRowView rowView)\n            {\n                var row = rowView.Row;\n                TxtRowIndex.Text = $\"Dòng thứ: {row.Table.Rows.IndexOf(row) + 2}\"; // +2 vì trừ header và index 0\n                \n                // Tóm tắt nội dung dòng\n                var values = row.ItemArray.Where(v => v != DBNull.Value && !string.IsNullOrEmpty(v.ToString())).Take(5);\n                TxtSummary.Text = string.Join(\", \", values);\n\n                // Gợi ý biểu đồ\n                SuggestChart(row);\n            }\n        }\n\n        private void SuggestChart(DataRow row)\n        {\n            int numericCount = 0;\n            foreach (var item in row.ItemArray)\n            {\n                if (item is double || item is int || item is decimal) numericCount++;\n            }\n\n            if (numericCount == 0)\n            {\n                TxtChartSuggestion.Text = \"Dòng này chủ yếu là văn bản. Phù hợp để làm nhãn hoặc mô tả.\";\n            }\n            else if (numericCount == 1)\n            {\n                TxtChartSuggestion.Text = \"Có 1 giá trị số. Phù hợp với biểu đồ Pie (tròn) để so sánh tỷ trọng.\";\n            }\n            else\n            {\n                TxtChartSuggestion.Text = \"Có nhiều giá trị số. Phù hợp với biểu đồ Column (cột) hoặc Line (đường) để xem xu hướng.\";\n            }\n        }\n\n        private void AddTask_Click(object sender, RoutedEventArgs e)\n        {\n            if (DgData.SelectedItem is DataRowView rowView)\n            {\n                var row = rowView.Row;\n                var desc = $\"Task từ dòng {row.Table.Rows.IndexOf(row) + 2}: {TxtSummary.Text}\";\n                _tasks.Add(new TaskItem { Description = desc, IsDone = false });\n                LbTasks.Items.Refresh();\n            }\n            else\n            {\n                MessageBox.Show(\"Vui lòng chọn một dòng dữ liệu trước khi thêm Task.\");\n            }\n        }\n\n        private void ShowChartDemo_Click(object sender, RoutedEventArgs e)\n        {\n            MessageBox.Show(\"Tính năng vẽ biểu đồ thực tế sẽ cần tích hợp thêm thư viện như LiveCharts2. Hiện tại đây là demo logic gợi ý.\", \"Thông báo\");\n        }\n    }\n\n    public class TaskItem\n    {\n        public string Description { get; set; } = \"\";\n        public bool IsDone { get; set; }\n    }\n}",
