```"},{"id":"steps-1ehixf2","type":"steps","steps":[{"id":"step_pcm5dc7","type":"generic","title":"📝 Modify File: ...elPlanner/ViewModels/MainViewModel.cs","input":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/ViewModels/MainViewModel.cs","output":"{"status":"success","data":{"status":"success","message":"Đã tìm kiếm và thay thế an toàn trong khoảng dòng 76 đến 85 (sau 1 lần thử)","file":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/ViewModels/MainViewModel.cs","absolute_path":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/ViewModels/MainViewModel.cs","directory":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/ViewModels","validations_passed":{"syntax":true,"logic_review":true,"shadow_backup":true},"attempts":1,"incremental_diff":{"file":"C:/Users/Xon/Desktop/ai_work/ExcelPlanner/ViewModels/MainViewModel.cs","additions":4,"deletions":4,"diff":"  using System.Collections.ObjectModel;\n  using System.Data;\n  using System.Windows;\n  using ClosedXML.Excel;\n  using ExcelPlanner.Commands;\n  using ExcelPlanner.Models;\n  using ExcelPlanner.Services;\n  using Microsoft.Win32;\n  \n  namespace ExcelPlanner.ViewModels\n  {\n      public class MainViewModel : ObservableObject\n      {\n          private readonly ExcelService _excelService;\n          private readonly PdfReportService _pdfService;\n          private XLWorkbook? _workbook;\n          private DataTable? _currentTable;\n          private string? _currentFileName;\n  \n          private string _statusText = \"Sẵn sàng\";\n          public string StatusText\n          {\n              get => _statusText;\n              set => SetProperty(ref _statusText, value);\n          }\n  \n          private List<string> _sheetNames = new();\n          public List<string> SheetNames\n          {\n              get => _sheetNames;\n              set => SetProperty(ref _sheetNames, value);\n          }\n  \n          private string? _selectedSheetName;\n          public string? SelectedSheetName\n          {\n              get => _selectedSheetName;\n              set\n              {\n                  if (SetProperty(ref _selectedSheetName, value))\n                  {\n                      LoadSheetData(value);\n                  }\n              }\n          }\n  \n          private DataView? _dataView;\n          public DataView? DataView\n          {\n              get => _dataView;\n              set => SetProperty(ref _dataView, value);\n          }\n  \n          private string _rowIndexInfo = \"\";\n          public string RowIndexInfo\n          {\n              get => _rowIndexInfo;\n              set => SetProperty(ref _rowIndexInfo, value);\n          }\n  \n          private string _rowSummary = \"\";\n          public string RowSummary\n          {\n              get => _rowSummary;\n              set => SetProperty(ref _rowSummary, value);\n          }\n  \n          private string _chartSuggestion = \"\";\n          public string ChartSuggestion\n          {\n              get => _chartSuggestion;\n              set => SetProperty(ref _chartSuggestion, value);\n          }\n  \n          public ObservableCollection<TaskItem> Tasks { get; } = new();\n  \n          public RelayCommand OpenFileCommand { get; }\n          public RelayCommand AddTaskCommand { get; }\n          public RelayCommand<object?> SelectionChangedCommand { get; }\n          public RelayCommand ExportPdfCommand { get; }\n  \n          public MainViewModel()\n          {\n              _excelService = new ExcelService();\n              _pdfService = new PdfReportService();\n              \n-             OpenFileCommand = new RelayCommand(_ => OpenFile());\n-             AddTaskCommand = new RelayCommand(_ => AddTask(), _ => DataView != null && SelectedRow != null);\n-             SelectionChangedCommand = new RelayCommand<object?>(param => UpdateSelectionInfo(param));\n-             ExportPdfCommand = new RelayCommand(_ => ExportToPdf(), _ => Tasks.Any());\n+             OpenFileCommand = new RelayCommand(OpenFile);\n+             AddTaskCommand = new RelayCommand(AddTask, () => DataView != null && SelectedRow != null);\n+             SelectionChangedCommand = new RelayCommand<object?>(UpdateSelectionInfo);\n+             ExportPdfCommand = new RelayCommand(ExportToPdf, () => Tasks.Any());\n          }\n  \n          private DataRowView? _selectedRow;\n          public DataRowView? SelectedRow\n          {\n              get => _selectedRow;\n              set\n              {\n                  if (SetProperty(ref _selectedRow, value))\n                  {\n                      AddTaskCommand.RaiseCanExecuteChanged();\n                  }\n              }\n          }\n  \n          private async void OpenFile()\n          {\n              var dialog = new OpenFileDialog\n              {\n                  Filter = \"Excel Files|*.xlsx;*.xls\",\n                  Title = \"Chọn file Excel để xem và lập kế hoạch\"\n              };\n  \n              if (dialog.ShowDialog() == true)\n              {\n                  try\n                  {\n                      StatusText = \"Đang tải file...\";\n                      _currentFileName = System.IO.Path.GetFileName(dialog.FileName);\n                      _workbook = await _excelService.LoadWorkbookAsync(dialog.FileName);\n                      SheetNames = _excelService.GetSheetNames(_workbook);\n                      \n                      if (SheetNames.Count > 0)\n                      {\n                          SelectedSheetName = SheetNames[0];\n                      }\n                      StatusText = $\"Đã mở: {_currentFileName}\";\n                  }\n                  catch (Exception ex)\n                  {\n                      MessageBox.Show($\"Lỗi đọc file: {ex.Message}\", \"Lỗi\", MessageBoxButton.OK, MessageBoxImage.Error);\n                      StatusText = \"Lỗi tải file\";\n                  }\n              }\n          }\n  \n          private async void LoadSheetData(string? sheetName)\n          {\n              if (_workbook == null || string.IsNullOrEmpty(sheetName)) return;\n  \n              try\n              {\n                  StatusText = \"Đang tải dữ liệu sheet...\";\n                  _currentTable = await _excelService.GetSheetDataAsync(_workbook, sheetName);\n                  DataView = _currentTable?.DefaultView;\n                  \n                  StatusText = _currentTable == null \n                      ? $\"Sheet: {sheetName} (Trống)\" \n                      : $\"Sheet: {sheetName} ({_currentTable.Rows.Count} dòng)\";\n              }\n              catch (Exception ex)\n              {\n                  MessageBox.Show($\"Không thể đọc sheet '{sheetName}': {ex.Message}\", \"Lỗi dữ liệu\", MessageBoxButton.OK, MessageBoxImage.Warning);\n                  StatusText = \"Lỗi đọc sheet\";\n              }\n          }\n  \n          private void UpdateSelectionInfo(object? parameter)\n          {\n              if (parameter is DataRowView rowView)\n              {\n                  SelectedRow = rowView;\n                  var row = rowView.Row;\n                  RowIndexInfo = $\"Dòng thứ: {row.Table.Rows.IndexOf(row) + 2}\";\n                  \n                  // Sửa lỗi CS8602 bằng cách kiểm tra null kỹ hơn\n                  var values = row.ItemArray\n                      .Where(v => v != DBNull.Value && v != null && !string.IsNullOrEmpty(v.ToString()))\n                      .Select(v => v!.ToString())\n                      .Take(5);\n                      \n                  RowSummary = string.Join(\", \", values);\n                  SuggestChart(row);\n              }\n          }\n  \n          private void SuggestChart(DataRow row)\n          {\n              int numericCount = 0;\n              foreach (var item in row.ItemArray)\n              {\n                  if (item is double or int or decimal) numericCount++;\n              }\n  \n              ChartSuggestion = numericCount switch\n              {\n                  0 => \"Dòng này chủ yếu là văn bản. Phù hợp để làm nhãn hoặc mô tả.\",\n                  1 => \"Có 1 giá trị số. Phù hợp với biểu đồ Pie (tròn) để so sánh tỷ trọng.\",\n                  _ => \"Có nhiều giá trị số. Phù hợp với biểu đồ Column (cột) hoặc Line (đường) để xem xu hướng.\"\n              };\n          }\n  \n          private void AddTask()\n          {\n              if (SelectedRow == null) return;\n  \n              var row = SelectedRow.Row;\n              var desc = $\"Task từ dòng {row.Table.Rows.IndexOf(row) + 2}: {RowSummary}\";\n              Tasks.Add(new TaskItem { Description = desc, IsDone = false });\n              ExportPdfCommand.RaiseCanExecuteChanged();\n          }\n  \n          private void ExportToPdf()\n          {\n              var dialog = new SaveFileDialog\n              {\n                  Filter = \"PDF Files|*.pdf\",\n                  Title = \"Lưu báo cáo kế hoạch\",\n                  FileName = $\"KeHoach_{_currentFileName ?? \"Export\"}.pdf\"\n              };\n  \n              if (dialog.ShowDialog() == true)\n              {\n                  try\n                  {\n                      _pdfService.GenerateTaskReport(dialog.FileName, _currentFileName ?? \"Excel Planner\", Tasks.ToList());\n                      MessageBox.Show(\"Xuất báo cáo PDF thành công!\", \"Thành công\", MessageBoxButton.OK, MessageBoxImage.Information);\n                  }\n                  catch (Exception ex)\n                  {\n                      MessageBox.Show($\"Lỗi xuất PDF: {ex.Message}\", \"Lỗi\", MessageBoxButton.OK, MessageBoxImage.Error);\n                  }\n              }\n          }\n      }\n  }\n  "}}}"}]},{"id":"text-s0mcfb4","type":"text","content":"Tôi đã điều chỉnh xong cách sử dụng `RelayCommand`. Bây giờ hãy thử biên dịch lại dự án để kiểm tra xem mọi thứ đã ổn chưa.

