73 |   const [loading, setLoading] = useState<boolean>(true);
74 |   const [error, setError] = useState<string | null>(null);
75 | 
76 |   const fetchDiff = useCallback(() => {
77 |     setLoading(true);
78 |     fetch('/api/dashboard/code-changes')
79 |       .then((res) => {
80 |         if (!res.ok) throw new Error("HTTP error " + res.status);
81 |         return res.json();
82 |       })
83 |       .then((data) => {
84 |         if (data.success && Array.isArray(data.changes)) {
85 |           const matched = data.changes.find((c: any) => {
86 |             const cFile = cleanPath(c.file);
87 |             const fFile = cleanPath(filePath);
88 |             return cFile.endsWith(fFile) || fFile.endsWith(cFile) || pathBasename(cFile) === pathBasename(fFile);
89 |           });
90 | 
91 |           if (matched && matched.diff) {
92 |             setDiffText(matched.diff);
93 |           } else {
94 |             setDiffText(null);
95 |           }
96 |         }
97 |         setLoading(false);
98 |       })
99 |       .catch((err) => {
100 |         setError(err.message);
101 |         setLoading(false);
102 |       });
103 |   }, [filePath]);
104 | 
105 |   useEffect(() => {
106 |     fetchDiff();
107 |   }, [fetchDiff]);
108 | 
109 |   const lines = useMemo(() => {
