119 |   }
120 | 
121 |   if (error) {
122 |     return (
123 |       <div className="text-red-500 text-[10px] py-1 select-none">
124 |         ❌ Không thể tải Git Diff: {error}
125 |       </div>
126 |     );
127 |   }
