129 |   if (!diffText) {
130 |     return (
131 |       <div className="text-zinc-500 text-[10px] italic bg-zinc-50 p-2.5 rounded-lg border border-zinc-200 select-none">
132 |         ℹ️ Không có thay đổi so với phiên bản gốc (Git Worktree sạch).
133 |       </div>
