144 |           type="button"
145 |           onClick={fetchDiff}
146 |           className="text-[9px] text-blue-600 hover:text-blue-500 font-semibold cursor-pointer"
147 |         >
148 |           Nạp lại 🔄
149 |         </button>
150 |       </div>
151 |       <div className="p-2.5 bg-zinc-900 text-zinc-100 overflow-x-auto max-h-80 font-mono text-[11px] leading-relaxed border-t border-zinc-800">
152 |         {lines.map((line, idx) => {
153 |           const isAdd = line.startsWith('+') && !line.startsWith('+++');
154 |           const isDel = line.startsWith('-') && !line.startsWith('---');
