462 | function parseContentAndMermaid(content: string) {
463 |   const regex = /```mermaid\n([\s\S]*?)```/g;
464 |   const parts = [];
465 |   let lastIndex = 0;
466 |   let match;
467 | 
468 |   while ((match = regex.exec(content)) !== null) {
469 |     const textBefore = content.substring(lastIndex, match.index);
470 |     if (textBefore.trim()) {
471 |       parts.push({ type: 'markdown', content: textBefore });
472 |     }
473 |     parts.push({ type: 'mermaid', content: match[1] });
474 |     lastIndex = regex.lastIndex;
475 |   }
476 | 
477 |   const textAfter = content.substring(lastIndex);
478 |   if (textAfter.trim() || parts.length === 0) {
479 |     parts.push({ type: 'markdown', content: textAfter });
480 |   }
481 | 
482 |   return parts;
483 | }
