485 | const getMessageTimeline = (msg: ChatMessage, msgIdx: number): TimelineItem[] => {
486 |   if (msg.timeline && msg.timeline.length > 0) {
487 |     return msg.timeline;
488 |   }
489 | 
490 |   const reconstructed: TimelineItem[] = [];
491 |   if (msg.steps && msg.steps.length > 0) {
492 |     reconstructed.push({
493 |       id: `reconstructed-steps-${msgIdx}-${msg.steps.length}`,
494 |       type: 'steps',
495 |       steps: msg.steps
496 |     });
497 |   }
498 |   if (msg.content && msg.content.trim()) {
499 |     reconstructed.push({
500 |       id: `reconstructed-text-${msgIdx}`,
501 |       type: 'text',
502 |       content: msg.content
503 |     });
504 |   }
505 |   return reconstructed;
506 | };
