163 | const DiffViewer = React.memo(function DiffViewer({ filePath }: DiffViewerProps) {
164 |   const [diffText, setDiffText] = useState<string | null>(null);
165 |   const [loading, setLoading] = useState<boolean>(true);
166 |   const [error, setError] = useState<string | null>(null);
167 | 
168 |   const fetchDiff = useCallback(() => {
169 |     setLoading(true);
170 |     fetch('/api/dashboard/code-changes')
171 |       .then((res) => {
172 |         if (!res.ok) throw new Error("HTTP error " + res.status);
173 |         return res.json();
174 |       })
175 |       .then((data) => {
176 |         if (data.success && Array.isArray(data.changes)) {
177 |           const matched = data.changes.find((c: any) => {
178 |             const cFile = cleanPath(c.file);
179 |             const fFile = cleanPath(filePath);
180 |             return cFile.endsWith(fFile) || fFile.endsWith(cFile) || pathBasename(cFile) === pathBasename(fFile);
181 |           });
182 | 
183 |           if (matched && matched.diff) {
184 |             setDiffText(matched.diff);
185 |           } else {
186 |             setDiffText(null);
187 |           }
188 |         }
189 |         setLoading(false);
190 |       })
191 |       .catch((err) => {
192 |         setError(err.message);
193 |         setLoading(false);
194 |       });
195 |   }, [filePath]);
196 | 
197 |   useEffect(() => {
198 |     fetchDiff();
199 |   }, [fetchDiff]);
200 | 
201 |   const lines = useMemo(() => {
202 |     return diffText ? diffText.split('\n') : [];
203 |   }, [diffText]);
204 | 
205 |   if (loading) {
206 |     return (
207 |       <div className="text-zinc-400 text-[10px] italic py-1 select-none">
208 |         ⌛ Đang so sánh thay đổi với Git Worktree...
209 |       </div>
210 |     );
211 |   }
212 | 
213 |   if (error) {
214 |     return (
215 |       <div className="text-red-500 text-[10px] py-1 select-none">
216 |         ❌ Không thể tải Git Diff: {error}
217 |       </div>
218 |     );
219 |   }
220 | 
221 |   if (!diffText) {
222 |     return (
223 |       <div className="text-zinc-500 text-[10px] italic bg-zinc-50 p-2.5 rounded-lg border border-zinc-200 select-none">
224 |         ℹ️ Không có thay đổi so với phiên bản gốc (Git Worktree sạch).
225 |       </div>
226 |     );
227 |   }
228 | 
229 |   return (
230 |     <div className="border border-zinc-200 rounded-xl overflow-hidden bg-white shadow-xs my-1 select-text">
231 |       <div className="bg-zinc-50 border-b border-zinc-200 px-3 py-1.5 flex items-center justify-between select-none">
232 |         <span className="text-[10px] font-bold text-zinc-700 flex items-center gap-1.5">
233 |           <span>📊</span> Git Sandbox Diff
234 |         </span>
235 |         <button
236 |           type="button"
237 |           onClick={fetchDiff}
238 |           className="text-[9px] text-blue-600 hover:text-blue-500 font-semibold cursor-pointer"
239 |         >
240 |           Nạp lại 🔄
241 |         </button>
242 |       </div>
243 |       <div className="p-2.5 bg-zinc-900 text-zinc-100 overflow-x-auto max-h-80 font-mono text-[11px] leading-relaxed border-t border-zinc-800">
244 |         {lines.map((line, idx) => {
245 |           const isAdd = line.startsWith('+') && !line.startsWith('+++');
246 |           const isDel = line.startsWith('-') && !line.startsWith('---');
247 |           const isMeta = line.startsWith('@@');
248 | 
249 |           let bgClass = "";
250 |           let prefix = "";
251 |           let codeContent = line;
252 | 
253 |           if (isAdd) {
254 |             bgClass = "bg-emerald-950/40 border-l-2 border-emerald-500 pl-1";
255 |             prefix = "+ ";
256 |             codeContent = line.substring(1);
257 |           } else if (isDel) {
258 |             bgClass = "bg-rose-950/40 border-l-2 border-rose-500 pl-1";
259 |             prefix = "- ";
260 |             codeContent = line.substring(1);
261 |           } else if (isMeta) {
262 |             bgClass = "bg-cyan-950/30 border-l-2 border-cyan-500 pl-1";
263 |           }
264 | 
265 |           const highlightedHtml = highlightCodeLine(codeContent);
266 | 
267 |           return (
268 |             <div key={idx} className={`whitespace-pre py-0.5 ${bgClass}`}>
269 |               {prefix && (
270 |                 <span className={isAdd ? "text-emerald-500 font-bold mr-1 select-none" : "text-rose-500 font-bold mr-1 select-none"}>
271 |                   {prefix}
272 |                 </span>
273 |               )}
274 |               {isAdd || isDel || (!line.startsWith('diff') && !line.startsWith('index') && !line.startsWith('---') && !line.startsWith('+++') && !line.startsWith('@@')) ? (
275 |                 <span dangerouslySetInnerHTML={{ __html: highlightedHtml }} />
