578 |   if (msg.timeline && msg.timeline.length > 0) {
579 |     return msg.timeline;
580 |   }
581 | 
582 |   const reconstructed: TimelineItem[] = [];
583 |   if (msg.steps && msg.steps.length > 0) {
584 |     reconstructed.push({
585 |       id: `reconstructed-steps-${msgIdx}-${msg.steps.length}`,
586 |       type: 'steps',
587 |       steps: msg.steps
588 |     });
589 |   }
590 |   if (msg.content && msg.content.trim()) {
591 |     reconstructed.push({
592 |       id: `reconstructed-text-${msgIdx}`,
593 |       type: 'text',
594 |       content: msg.content
595 |     });
596 |   }
597 |   return reconstructed;
598 | };
