259 |             prefix = "- ";
260 |             codeContent = line.substring(1);
261 |           } else if (isMeta) {
262 |             bgClass = "bg-cyan-950/30 border-l-2 border-cyan-500 pl-1";
263 |           }
264 | 
265 |           const highlightedHtml = highlightCodeLine(codeContent);
