554 | function parseContentAndMermaid(content: string) {
555 |   const regex = /```mermaid\n([\s\S]*?)```/g;
556 |   const parts = [];
557 |   let lastIndex = 0;
558 |   let match;
559 | 
560 |   while ((match = regex.exec(content)) !== null) {
561 |     const textBefore = content.substring(lastIndex, match.index);
562 |     if (textBefore.trim()) {
563 |       parts.push({ type: 'markdown', content: textBefore });
564 |     }
565 |     parts.push({ type: 'mermaid', content: match[1] });
566 |     lastIndex = regex.lastIndex;
567 |   }
568 | 
569 |   const textAfter = content.substring(lastIndex);
570 |   if (textAfter.trim() || parts.length === 0) {
571 |     parts.push({ type: 'markdown', content: textAfter });
572 |   }
573 | 
574 |   return parts;
575 | }
